def decimal_to_Octal(decimal):
    octal_digits = []
    if decimal == 0:
        return "0"
    while decimal > 0:
        remainder = decimal % 8
        octal_digits.append(str(remainder))
        decimal //= 8
    return "".join(octal_digits[::-1])

def decimal_to_Octal(decimal_num: int) -> str:
    octal_num = ""
    while decimal_num > 0:
        remainder = decimal_num % 8
        octal_num = str(remainder) + octal_num
        decimal_num //= 8
    if not octal_num:
        return "0"
    return octal_num

def decimal_to_Octal(dec):
    if dec == 0:
        return "0"
    octal_num = ""
    while dec > 0:
        remainder = dec % 8
        octal_num = str(remainder) + octal_num
        dec //= 8
    return octal_num

def shell_sort(arr):
    n = len(arr)
    gap = n // 2
    while gap > 0:
        for i in range(gap, n):
            temp = arr[i]
            j = i
            while j >= gap and arr[j - gap] > temp:
                arr[j] = arr[j - gap]
                j -= gap
            arr[j] = temp
        gap //= 2
    return arr

