def count_unset_bits(n):
    count = 0
    temp_n = n

    if n == 0:
        return 1 # For 0, there is one unset bit (the 0th bit)

    while temp_n > 0:
        if (temp_n & 1) == 0:
            count += 1
        temp_n >>= 1

    return count

