def find_ways(n, k):
    if k > n:
        return 0

    dp = [[0] * (k + 1) for _ in range(n + 1)]

    for i in range(k + 1):
        dp[0][i] = 1

    for i in range(1, n + 1):
        for j in range(k + 1):
            if j == 0:
                dp[i][j] = dp[i-1][j+1]
            elif j == k:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = dp[i-1][j-1] + dp[i-1][j+1]

    return dp[n][0]

def find_ways(N, K):
    dp = [[0] * (K + 1) for _ in range(N + 1)]
    dp[0][0] = 1
    for i in range(1, N + 1):
        for j in range(K + 1):
            if j - 1 >= 0:
                dp[i][j] += dp[i - 1][j - 1]
            if j + 1 <= K:
                dp[i][j] += dp[i - 1][j + 1]
    return dp[N][0]

def find_ways(N, A):
    """
    Counts the number of sequences of length N having non-negative prefix sums
    that can be generated by values in list A.
    """
    if sum(A) != 0:
        return 0

    dp = {}

    def solve(index, current_sum):
        if (index, current_sum) in dp:
            return dp[(index, current_sum)]

        if index == N:
            return 1 if current_sum == 0 else 0

        if current_sum < 0:
            return 0

        count = 0
        for val in A:
            count += solve(index + 1, current_sum + val)

        dp[(index, current_sum)] = count
        return count

    return solve(0, 0)

def find_ways(N, A):
    """
    Counts sequences of given length having non-negative prefix sums that can be generated by given values.

    Args:
        N: The length of the sequence.
        A: A list of integers representing the allowed values.

    Returns:
        The number of valid sequences.
    """
    if not A:
        return 0

    dp = [[0] * (N + 1) for _ in range(N + 1)]
    dp[0][0] = 1

    for i in range(1, N + 1):
        for j in range(N + 1):
            for x in A:
                if 0 <= j - x <= N:
                    dp[i][j] += dp[i - 1][j - x]

    ans = 0
    for j in range(N + 1):
        ans += dp[N][j]
    return ans

