        nonlocal count
        if len(current_sequence) == length:
            count += 1
            return

        for val in arr:
            if current_sum + val >= 0:
                current_sequence.append(val)
                generate_sequences(current_sequence, current_sum + val)
                current_sequence.pop()

    generate_sequences([], 0)
    return count

