def find_ways(values, length):
    memo = {}

    def dp(current_sum, remaining_length):
        if remaining_length == 0:
            return 1 if current_sum >= 0 else 0

        if (current_sum, remaining_length) in memo:
            return memo[(current_sum, remaining_length)]

        count = 0
        for val in values:
            if current_sum + val >= 0:
                count += dp(current_sum + val, remaining_length - 1)

        memo[(current_sum, remaining_length)] = count
        return count

    return dp(0, length)

def find_ways(n, s, vals):
    dp = {}

    def solve(index, current_sum):
        if (index, current_sum) in dp:
            return dp[(index, current_sum)]

        if index == n:
            return 1 if current_sum >= 0 else 0

        if current_sum < 0:
            return 0

        ways = 0
        for val in vals:
            ways += solve(index + 1, current_sum + val)

        dp[(index, current_sum)] = ways
        return ways

    return solve(0, s)

def find_ways(n, s):
    dp = [[0] * (s + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in 0, 1:
            for k in range(j, s + 1):
                dp[i][k] += dp[i - 1][k - j]

    return dp[n][s]

def find_ways(n, k):
    dp = [[0 for _ in range(k + 1)] for _ in range(n + 1)]

    for i in range(k + 1):
        dp[0][i] = 1

    for i in range(1, n + 1):
        for j in range(k + 1):
            dp[i][j] = dp[i - 1][j]
            if j > 0:
                dp[i][j] += dp[i][j - 1]
    return dp[n][k]

def find_ways(total_sum, n):
    dp = [[0] * (total_sum + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(total_sum + 1):
            # Option 1: Add a +1
            if j - 1 >= 0:
                dp[i][j] += dp[i - 1][j - 1]
            # Option 2: Add a -1
            if j + 1 <= total_sum:
                dp[i][j] += dp[i - 1][j + 1]
    return dp[n][0]

