    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(k + 1):
            # Include the current number arr[i-1]
            for prev_sum in range(j + 1):
                if dp[i - 1][prev_sum] > 0:
                    current_sum = prev_sum + arr[i - 1]
                    if current_sum >= 0 and current_sum <= j:
                        dp[i][j] += dp[i - 1][prev_sum]

