def find_ways(n, s, vals):
    dp = [[0] * (2 * n + 1) for _ in range(n + 1)]
    dp[0][n] = 1  # Base case: 0 length sequence, prefix sum 0 (offset by n)

    for i in range(1, n + 1):
        for j in range(2 * n + 1):
            for val in vals:
                prev_sum_idx = j - val
                if 0 <= prev_sum_idx <= 2 * n and j >= n:  # Ensure prefix sum is non-negative (j >= n)
                    dp[i][j] += dp[i - 1][prev_sum_idx]
    return dp[n][s + n]

def find_ways(n, s):
