def comb_sort(my_list):
    n = len(my_list)
    gap = n
    shrink_factor = 1.3
    swapped = True

    while gap > 1 or swapped:
        if gap > 1:
            gap = int(gap / shrink_factor)

        swapped = False
        for i in range(n - gap):
            if my_list[i] > my_list[i + gap]:
                my_list[i], my_list[i + gap] = my_list[i + gap], my_list[i]
                swapped = True
    return my_list

