    return count

def extract_missing(lst, start, end):
    present_ranges = []
    for i in range(0, len(lst), 2):
        present_ranges.append((lst[i], lst[i+1]))

    missing_ranges = []
    current = start
    for r_start, r_end in sorted(present_ranges):
        if current < r_start:
            missing_ranges.append((current, r_start - 1))
        current = max(current, r_end + 1)

    if current <= end:
        missing_ranges.append((current, end))

    return missing_ranges

