    high = n - 1
    while low <= high:
        mid = (low + high) // 2
        if (mid == 0 or arr[mid] != arr[mid - 1]) and \
           (mid == n - 1 or arr[mid] != arr[mid + 1]):
            return arr[mid]
        elif mid % 2 == 0:
            if arr[mid] == arr[mid + 1]:
                low = mid + 2
            else:
                high = mid - 2
        else:
