def find_Nth_Digit(numerator, denominator, n):
    fraction_value = numerator / denominator
    fraction_str = str(fraction_value)

    if '.' not in fraction_str:
        return 0

    decimal_part = fraction_str.split('.')[1]

    if n <= len(decimal_part):
        return int(decimal_part[n - 1])
    else:
        return 0

def find_Nth_Digit(numerator, denominator, n):
    if n <= 0:
        return None

    # Calculate the fractional part
    fractional_part = numerator / denominator

    # Convert to string and find the Nth digit
    s = str(fractional_part)

    # Check if there is a decimal point
    if '.' in s:
        decimal_index = s.index('.')

        # If n is beyond the available digits
        if decimal_index + n >= len(s):
            # This implies the fraction might be terminating or repeating after a certain point.
            # For simplicity, we can assume it's 0 if we run out of digits in the string representation.
            # More robust solutions for repeating decimals would involve tracking remainders.
            return 0 
        else:
            return int(s[decimal_index + n])
    else:
        # If the number is an integer, there are no digits after the decimal point
        return 0 if n > 0 else None

