def find_Nth_Digit(numerator, denominator, n):
    if n <= 0:
        return None

    fraction_value = numerator / denominator
    fraction_str = str(fraction_value)

    if '.' in fraction_str:
        decimal_part = fraction_str.split('.')[1]
        if n <= len(decimal_part):
            return int(decimal_part[n - 1])
        else:

            remainder = numerator % denominator
            seen_remainders = {}
            decimal_digits = []
            index = 0

            while remainder != 0 and remainder not in seen_remainders:
                seen_remainders[remainder] = index
                remainder *= 10
                decimal_digits.append(remainder // denominator)
                remainder %= denominator
                index += 1

            if remainder == 0:
                if n <= len(decimal_digits):
                    return decimal_digits[n - 1]
                else:
                    return 0
            else:

                non_repeating_part_len = seen_remainders[remainder]
                repeating_part_len = index - non_repeating_part_len


                if n <= non_repeating_part_len:
                    return decimal_digits[n - 1]
                else:
                    adjusted_n = n - non_repeating_part_len -1
                    return decimal_digits[non_repeating_part_len + (adjusted_n % repeating_part_len)]
    else:
        return 0

